from __future__ import annotations

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["dashboard"])


@router.get("/dashboard", response_class=HTMLResponse)
def dashboard_view() -> HTMLResponse:
    return HTMLResponse(DASHBOARD_HTML)


DASHBOARD_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ATLAS — Live Trading Intelligence</title>
<style>
:root{color-scheme:dark;--bg:#06080d;--card:#0d131d;--line:#253247;--text:#f2f5f9;--muted:#8e9bad;--orange:#ff8a24;--green:#39d98a;--red:#ff6174;--yellow:#f6c85f}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#172336 0,#06080d 42%);color:var(--text);font:14px Inter,system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:22px}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}.brand{display:flex;gap:12px;align-items:center}.logo{width:46px;height:46px;border:1px solid var(--orange);border-radius:15px;display:grid;place-items:center;font-weight:900;color:var(--orange)}.title{font-size:23px;font-weight:900;letter-spacing:.05em}.sub,.mini{font-size:11px;color:var(--muted)}.actions{display:flex;gap:8px;align-items:center}.btn{color:#090b0f;background:var(--orange);text-decoration:none;padding:10px 13px;border-radius:11px;font-weight:900}.badge{border:1px solid var(--line);padding:9px 11px;border-radius:999px;font-weight:800}.grid{display:grid;gap:12px}.stats{grid-template-columns:repeat(6,1fr)}.split{grid-template-columns:1.65fr 1fr}.card{background:linear-gradient(180deg,#111824,#0b111a);border:1px solid var(--line);border-radius:17px;padding:16px;box-shadow:0 16px 45px #0006}.label{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.11em}.big{font-size:24px;font-weight:900;margin-top:6px}.green{color:var(--green)}.red{color:var(--red)}.yellow{color:var(--yellow)}.orange{color:var(--orange)}.row{display:grid;grid-template-columns:1.2fr .8fr .7fr .7fr .65fr;gap:8px;padding:10px 0;border-bottom:1px solid var(--line);align-items:center}.pos{display:grid;grid-template-columns:1fr .65fr .75fr .7fr;gap:8px;padding:9px 0;border-bottom:1px solid var(--line)}.tag{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:4px 8px;font-size:10px}.empty{color:var(--muted);padding:12px 0}.notice{border-left:3px solid var(--orange);padding:10px 12px;background:#ff8a240b;border-radius:8px;color:#bdc7d3;margin-top:12px}@media(max-width:1100px){.stats{grid-template-columns:repeat(3,1fr)}.split{grid-template-columns:1fr}}@media(max-width:720px){main{padding:12px}.stats{grid-template-columns:1fr 1fr}.top{align-items:flex-start;flex-direction:column}.row,.pos{grid-template-columns:1fr 1fr}}
</style></head><body><main>
<div class="top"><div class="brand"><div class="logo">A</div><div><div class="title">ATLAS THE ULTIMATE</div><div class="sub">Subscriber Observatory · Read-only live telemetry</div></div></div><div class="actions"><a class="btn" href="/subscribe">Subscriber plans</a><div class="badge" id="status">CONNECTING</div></div></div>
<div class="grid stats"><div class="card"><div class="label">Account Type</div><div class="big" id="accountType">—</div></div><div class="card"><div class="label">Equity</div><div class="big" id="equity">—</div></div><div class="card"><div class="label">Balance</div><div class="big" id="balance">—</div></div><div class="card"><div class="label">Floating P/L</div><div class="big" id="floating">—</div></div><div class="card"><div class="label">Open Positions</div><div class="big" id="openPositions">—</div></div><div class="card"><div class="label">Execution Gate</div><div class="big yellow" id="execution">—</div></div></div>
<div class="grid split" style="margin-top:12px"><section class="card"><div class="label">ATLAS Opportunity Matrix</div><div id="signals"></div></section><section class="card"><div class="label">Verified Account</div><div id="account"></div><div class="label" style="margin-top:18px">Open Positions</div><div id="positions"></div></section></div>
<div class="notice" id="disclaimer">Read-only telemetry. Trading involves risk.</div></main>
<script>
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\'':'&#39;','"':'&quot;'}[c]));const money=(v,c='')=>v===null||v===undefined?'PRIVATE':`${Number(v).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}${c?' '+c:''}`;const tone=v=>Number(v)>=0?'green':'red';async function refresh(){try{const r=await fetch('/dashboard/atlas',{cache:'no-store'});if(!r.ok)throw Error(`HTTP ${r.status}`);const d=await r.json(),a=d.account||{};status.textContent=d.verified_live_account?'VERIFIED LIVE':'ONLINE';accountType.textContent=a.account_type||'—';accountType.className='big '+(a.account_type==='REAL'?'green':'yellow');equity.textContent=money(a.equity,a.currency);balance.textContent=money(a.balance,a.currency);floating.textContent=money(d.floating_position_pnl,a.currency);floating.className='big '+tone(d.floating_position_pnl);openPositions.textContent=d.open_positions??0;execution.textContent=d.services.execution_gate;account.innerHTML=`<div class="pos"><span>${esc(a.label)}</span><b>${esc(a.login)}</b><span>${esc(a.server)}</span><b>1:${esc(a.leverage||'—')}</b></div>`;signals.innerHTML=(d.symbols||[]).map(x=>`<div class="row"><div><b>${esc(x.canonical_symbol||x.symbol)}</b><div class="mini">${esc(x.asset_class)} · ${esc(x.symbol)}</div></div><div><span class="tag">${esc(x.decision.bias)}</span><div class="mini">${esc(x.decision.decision)}</div></div><div><b>${Number(x.decision.score||0).toFixed(1)}</b><div class="mini">score</div></div><div><b>${Number(x.quality.execution_confidence||0).toFixed(1)}%</b><div class="mini">confidence</div></div><div><b>${Number(x.opportunity_score||0).toFixed(0)}</b><div class="mini">opportunity</div></div></div>`).join('')||'<div class="empty">No markets available.</div>';positions.innerHTML=(d.positions||[]).map(p=>`<div class="pos"><div><b>${esc(p.symbol)}</b><div class="mini">${esc(p.direction)}</div></div><div>${p.volume}</div><div>${p.price_open}</div><div class="${tone(p.profit)}"><b>${Number(p.profit||0).toFixed(2)}</b></div></div>`).join('')||'<div class="empty">No open positions.</div>';disclaimer.textContent=d.disclaimer}catch(e){status.textContent='OFFLINE'}}refresh();setInterval(refresh,5000);
</script></body></html>'''
